26	impl ImportKey {
27	    pub fn new(info: ImportInfo, groups: Option<&ImportGroups>) -> Self {
28	        Self {
29	            group: groups.map_or(0, |groups| groups.index(&((&info).into()))),
30	            source: info.source,
31	            has_no_attributes: info.has_no_attributes,
32	            kind: info.kind,
33	            slot_index: info.slot_index,
34	        }
35	    }
36	
37	    pub fn is_mergeable(&self, other: &Self) -> bool {
38	        self.source == other.source
39	            && self.kind.is_mergeable(other.kind.into())
40	            && self.has_no_attributes
41	            && other.has_no_attributes
42	    }
43	}
44	impl Ord for ImportKey {
45	    fn cmp(&self, other: &Self) -> Ordering {
46	        match self.group.cmp(&other.group) {
47	            Ordering::Equal => {}
48	            ord => return ord,
49	        }
50	        match (&self.source, &other.source) {
51	            (None, None) => {}
52	            (Some(_), None) => return Ordering::Less,
53	            (None, Some(_)) => return Ordering::Greater,
54	            (Some(self_source), Some(other_source)) => match self_source.cmp(other_source) {
55	                Ordering::Equal => {}
56	                ord => return ord,
57	            },
58	        }
59	        match self.has_no_attributes.cmp(&other.has_no_attributes) {
60	            Ordering::Equal => {}
61	            ord => return ord,
62	        }
63	        match self.kind.cmp(&other.kind) {
64	            Ordering::Equal => {}
65	            ord => return ord,
66	        }
67	        self.slot_index.cmp(&other.slot_index)
68	    }
69	}
70	impl PartialOrd for ImportKey {
71	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
72	        Some(self.cmp(other))
73	    }
74	}
