/// Matches imports based on whether they are bare (side-effect only) imports.
#[derive(
    Clone, Copy, Debug, Deserializable, Eq, PartialEq, serde::Deserialize, serde::Serialize,
)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
pub enum ImportKindMatcher {
    /// Matches bare imports, i.e. imports without any binding such as `import "polyfill"`.
    #[serde(rename = "bare")]
    Bare,
    /// Matches imports that have at least one binding (default, named, or namespace import).
    #[serde(rename = "!bare")]
    NotBare,
}
impl ImportKindMatcher {
    fn is_match(self, candidate: &ImportCandidate<'_>) -> bool {
        match self {
            Self::Bare => candidate.is_bare,
            Self::NotBare => !candidate.is_bare,
