            (Some(_), None) => return Ordering::Less,
            (None, Some(_)) => return Ordering::Greater,
            (Some(self_source), Some(other_source)) => match self_source.cmp(other_source) {
                Ordering::Equal => {}
                ord => return ord,
            },
