pub struct ImportCandidate<'a> {
    pub has_type_token: bool,
    /// `true` if the import is a bare (side-effect only) import, i.e. it has no
    /// binding specifiers such as `import "polyfill"`.
    pub is_bare: bool,
    pub source: Option<ImportSourceCandidate<'a>>,
}
#[derive(
    Clone, Debug, Default, Eq, PartialEq, Deserializable, serde::Deserialize, serde::Serialize,
)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
pub struct ImportMatcher {
    kind: Option<ImportKindMatcher>,
    r#type: Option<bool>,
    source: Option<SourcesMatcher>,
}
impl ImportMatcher {
    pub fn is_match(&self, candidate: &ImportCandidate<'_>) -> bool {
        let matches_kind = self.kind.is_none_or(|kind| kind.is_match(candidate));
        let matches_type = self
            .r#type
            .is_none_or(|r#type| candidate.has_type_token == r#type);
        matches_kind
            && matches_type
            && self.source.as_ref().is_none_or(|src| {
                candidate
                    .source
                    .as_ref()
                    .is_some_and(|candidate_source| src.is_match(candidate_source))
            })
    }
}

/// Matches imports based on whether they are bare (side-effect only) imports.
#[derive(
    Clone, Copy, Debug, Deserializable, Eq, PartialEq, serde::Deserialize, serde::Serialize,
)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
pub enum ImportKindMatcher {
    /// Matches bare imports, i.e. imports without any binding such as `import "polyfill"`.
    #[serde(rename = "bare")]
    Bare,
    /// Matches imports that have at least one binding (default, named, or namespace import).
    #[serde(rename = "!bare")]
    NotBare,
}
impl ImportKindMatcher {
    fn is_match(self, candidate: &ImportCandidate<'_>) -> bool {
        match self {
            Self::Bare => candidate.is_bare,
            Self::NotBare => !candidate.is_bare,
        }
    }
}

